use std::sync::{Arc, Mutex};

pub struct Downloader {
    on_done: Option<Box<dyn FnOnce(Result<String, Error>) + Send>>,   // one-shot completion
}

impl Downloader {
    pub fn start(&mut self, url: String) {
        let cb = self.on_done.take().expect("callback already consumed");
        std::thread::spawn(move || cb(fetch(&url)));                  // runs exactly once
    }
}

pub fn subscribe<F: Fn(&Event) + Send + Sync + 'static>(&self, f: F) {
    self.listeners.lock().unwrap().push(Arc::new(f));
}
